// Hand-written Verilog testbench for AC-MVP-001, AC-MVP-002, AC-MVP-003 and
// AC-MVP-004. It is deliberately not generated by ShyHDL: a failure here must
// be a DUT failure, never a testbench-generation failure.
//
// The reference model is a bit-level ripple-carry adder (`ripple`), which never
// uses the `+` operator, so the DUT cannot pass by reproducing the expression
// the frontend itself emits.
//
// Protocol: exactly one `SHYHDL-AC-PASS adder ...` line on success, otherwise
// one or more `SHYHDL-AC-FAIL adder ...` lines plus a final FAIL summary. A run
// that prints no verdict at all is a failure, never a pass.
//
// Expects the frontend-generated modules: Add_N1, Add_N8, Adder8, AdderTop.

`timescale 1ns/1ps

module tb_adder;
    localparam integer EXPECTED_CHECKS_8 = 65536;
    localparam integer EXPECTED_CHECKS_1 = 4;

    reg [7:0] a8, b8;
    reg       a1, b1;

    wire [7:0] sum_n8, sum_wrap, sum_top8, sum_topw, sum_topo;
    wire       carry_n8, carry_wrap, carry_top8, carry_topw, carry_topo;
    wire       sum_n1, carry_n1, sum_top1, carry_top1;

    integer   i, j;
    integer   checks8, checks1, failures;
    reg [8:0] expected;

    Add_N8   dut_n8   (.a(a8), .b(b8), .sum(sum_n8), .carry(carry_n8));
    Add_N1   dut_n1   (.a(a1), .b(b1), .sum(sum_n1), .carry(carry_n1));
    Adder8   dut_wrap (.a(a8), .b(b8), .sum(sum_wrap), .carry(carry_wrap));
    AdderTop dut_top  (.a8(a8), .b8(b8), .a1(a1), .b1(b1),
                       .sum8(sum_top8), .carry8(carry_top8),
                       .osum8(sum_topo), .ocarry8(carry_topo),
                       .sum1(sum_top1), .carry1(carry_top1),
                       .wsum(sum_topw), .wcarry(carry_topw));

    function [8:0] ripple;
        input [7:0] x;
        input [7:0] y;
        integer   k;
        reg       c;
        reg [8:0] r;
        begin
            c = 1'b0;
            r = 9'b0;
            for (k = 0; k < 8; k = k + 1) begin
                r[k] = x[k] ^ y[k] ^ c;
                c = (x[k] & y[k]) | (x[k] & c) | (y[k] & c);
            end
            r[8] = c;
            ripple = r;
        end
    endfunction

    task mismatch;
        input [255:0] what;
        input [8:0]   got;
        input [8:0]   want;
        begin
            failures = failures + 1;
            if (failures <= 8)
                $display("SHYHDL-AC-FAIL adder %0s a8=%0d b8=%0d a1=%0d b1=%0d got=%b want=%b",
                         what, a8, b8, a1, b1, got, want);
        end
    endtask

    initial begin
        failures = 0;
        checks8 = 0;
        checks1 = 0;
        a8 = 8'h00;
        b8 = 8'h00;
        a1 = 1'b0;
        b1 = 1'b0;

        // AC-MVP-004 (N = 1) and AC-MVP-002 (the 1 + 1 wrap): all four inputs.
        for (i = 0; i < 2; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                a1 = i[0];
                b1 = j[0];
                #1;
                expected = ripple({7'b0, a1}, {7'b0, b1});
                checks1 = checks1 + 1;
                if ({carry_n1, sum_n1} !== expected[1:0])
                    mismatch("Add_N1", {carry_n1, sum_n1}, expected);
                if ({carry_top1, sum_top1} !== expected[1:0])
                    mismatch("AdderTop.sum1", {carry_top1, sum_top1}, expected);
            end
        end

        // AC-MVP-001 and AC-MVP-004 (N = 8) and AC-MVP-002 (widening carry):
        // every one of the 65536 input pairs, through the leaf module, the
        // wrapper and the two-level top.
        for (i = 0; i < 256; i = i + 1) begin
            a8 = i;
            for (j = 0; j < 256; j = j + 1) begin
                b8 = j;
                #1;
                expected = ripple(a8, b8);
                checks8 = checks8 + 1;
                if ({carry_n8, sum_n8} !== expected)
                    mismatch("Add_N8", {carry_n8, sum_n8}, expected);
                if ({carry_wrap, sum_wrap} !== expected)
                    mismatch("Adder8", {carry_wrap, sum_wrap}, expected);
                if ({carry_top8, sum_top8} !== expected)
                    mismatch("AdderTop.sum8", {carry_top8, sum_top8}, expected);
                if ({carry_topo, sum_topo} !== expected)
                    mismatch("AdderTop.other8", {carry_topo, sum_topo}, expected);
                if ({carry_topw, sum_topw} !== expected)
                    mismatch("AdderTop.wsum", {carry_topw, sum_topw}, expected);
            end
        end

        if (failures == 0 && checks8 == EXPECTED_CHECKS_8 && checks1 == EXPECTED_CHECKS_1)
            $display("SHYHDL-AC-PASS adder checks8=%0d checks1=%0d", checks8, checks1);
        else
            $display("SHYHDL-AC-FAIL adder failures=%0d checks8=%0d checks1=%0d",
                     failures, checks8, checks1);
        $finish;
    end

    initial begin
        #1000000;
        $display("SHYHDL-AC-FAIL adder timeout at %0t: no verdict was printed", $time);
        $finish;
    end
endmodule
